namespace Invoicing;

/// <summary>
/// Provides a stable facade for invoice, tax, reminder, fee and ledger operations.
/// </summary>
public sealed class BillingManager
{
    private readonly InvoiceService _invoices = new();
    private readonly TaxCalculator _tax = new();
    private readonly ReminderService _reminders = new();
    private readonly LateFeeCalculator _lateFees = new();
    private readonly LedgerService _ledger = new();

    public string CreateInvoice(Invoice invoice, Account account) =>
        _invoices.Create(invoice, account);

    public bool ValidateInvoice(Invoice invoice) =>
        _invoices.Validate(invoice);

    public int IssuedCount => _invoices.IssuedCount;

    public decimal ComputeTax(Invoice invoice, string countryCode) =>
        _tax.Compute(invoice, countryCode);

    public decimal ResolveRate(string countryCode) =>
        _tax.ResolveRate(countryCode);

    public decimal NetTotal(Invoice invoice) =>
        _tax.NetTotal(invoice);

    public string IssueReminder(Invoice invoice, Account account) =>
        _reminders.Issue(invoice, account);

    public int ReminderLevel(Invoice invoice) =>
        _reminders.GetLevel(invoice);

    public void Post(Invoice invoice, decimal amount) =>
        _ledger.Post(invoice, amount);

    public decimal Settle(Invoice invoice, decimal payment) =>
        _ledger.Settle(invoice, payment);

    public decimal ApplyLateFees(Invoice invoice, Account account) =>
        _lateFees.Calculate(invoice, account, _reminders.GetLevel(invoice));

    public string Reconcile(Account account) =>
        _ledger.Reconcile(account);

    public decimal Balance => _ledger.Balance;
}

internal sealed class InvoiceService
{
    private readonly List<string> _issuedNumbers = new();
    private int _nextSequence = 1;

    public int IssuedCount => _issuedNumbers.Count;

    public string Create(Invoice invoice, Account account)
    {
        if (string.IsNullOrEmpty(invoice.Number))
            invoice.Number = $"INV-{_nextSequence++:D6}";
        if (_issuedNumbers.Contains(invoice.Number))
            return "duplicate";
        if (invoice.Lines.Count == 0)
            return "empty";
        if (account.Kind == AccountKind.Government && string.IsNullOrEmpty(account.BillingAddress))
            return "po required";

        _issuedNumbers.Add(invoice.Number);
        return invoice.Number;
    }

    public bool Validate(Invoice invoice)
    {
        if (string.IsNullOrEmpty(invoice.Number) || invoice.Lines.Count == 0)
            return false;

        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m || line.VatRate < 0m || line.VatRate > 1m)
                return false;
        }

        return true;
    }
}

internal sealed class TaxCalculator
{
    private const decimal ReducedRate = 0.05m;

    private readonly Dictionary<string, decimal> _vatRates =
        new(StringComparer.OrdinalIgnoreCase)
        {
            ["GB"] = 0.20m,
            ["DE"] = 0.19m,
            ["FR"] = 0.20m,
        };

    public decimal Compute(Invoice invoice, string countryCode)
    {
        decimal tax = 0m;
        var defaultRate = ResolveRate(countryCode);

        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount <= 0m)
                continue;

            var rate = line.VatRate > 0m ? line.VatRate : defaultRate;
            if (rate > 0m)
                tax += line.NetAmount * rate;
        }

        return Math.Round(tax, 2);
    }

    public decimal ResolveRate(string countryCode)
    {
        if (!string.IsNullOrEmpty(countryCode) && _vatRates.TryGetValue(countryCode, out var rate))
            return rate;

        return ReducedRate;
    }

    public decimal NetTotal(Invoice invoice)
    {
        decimal net = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount > 0m)
                net += line.NetAmount;
        }

        return net;
    }
}

internal sealed class ReminderService
{
    private readonly Dictionary<string, int> _reminderCounts = new(StringComparer.Ordinal);

    public string Issue(Invoice invoice, Account account)
    {
        var count = GetStoredCount(invoice.Number);
        if (count >= 3)
            return "escalate";
        if (account.Kind == AccountKind.Government)
            return "no reminder";

        _reminderCounts[invoice.Number] = count + 1;
        if (count == 0)
            return "first notice";
        if (count == 1)
            return "second notice";
        return "final notice";
    }

    public int GetLevel(Invoice invoice) =>
        Math.Min(GetStoredCount(invoice.Number), 3);

    private int GetStoredCount(string invoiceNumber) =>
        _reminderCounts.TryGetValue(invoiceNumber, out var count) ? count : 0;
}

internal sealed class LateFeeCalculator
{
    public decimal Calculate(Invoice invoice, Account account, int reminderLevel)
    {
        if (string.IsNullOrEmpty(invoice.Number) || reminderLevel <= 0)
            return 0m;
        if (account.Kind == AccountKind.Government)
            return 0m;

        decimal fee = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount > 0m)
                fee += line.NetAmount * 0.01m * reminderLevel;
        }

        var maximumFee = account.Kind == AccountKind.Business ? 100m : 50m;
        return Math.Round(Math.Min(fee, maximumFee), 2);
    }
}

internal sealed class LedgerService
{
    private readonly List<string> _entries = new();
    private decimal _balance;

    public decimal Balance => _balance;

    public void Post(Invoice invoice, decimal amount)
    {
        if (amount == 0m)
            return;

        _entries.Add(amount > 0m
            ? $"DR {invoice.Number} {amount}"
            : $"CR {invoice.Number} {-amount}");
        _balance += amount;
    }

    public decimal Settle(Invoice invoice, decimal payment)
    {
        if (payment <= 0m || string.IsNullOrEmpty(invoice.Number))
            return _balance;

        _entries.Add($"PMT {invoice.Number} {payment}");
        _balance = Math.Max(0m, _balance - payment);
        return _balance;
    }

    public string Reconcile(Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return "no account";
        if (_entries.Count == 0)
            return "no entries";

        var (credits, debits) = CountEntryKinds();
        if (_balance > 0m && debits > credits)
            return "outstanding";
        if (_balance <= 0m)
            return "settled";
        return "partial";
    }

    private (decimal Credits, decimal Debits) CountEntryKinds()
    {
        decimal credits = 0m;
        decimal debits = 0m;

        foreach (var entry in _entries)
        {
            if (entry.StartsWith("CR", StringComparison.Ordinal) ||
                entry.StartsWith("PMT", StringComparison.Ordinal))
            {
                credits += 1m;
            }
            else if (entry.StartsWith("DR", StringComparison.Ordinal))
            {
                debits += 1m;
            }
        }

        return (credits, debits);
    }
}
